namespace wc {
const std::vector<std::string>& supported_categories(){static const std::vector<std::string>v={"operating-system","boot-kernel","packages","services","configuration","mounts","hardware","repositories"};return v;}
Category parse_rpm_query_output(const std::string& output){Category c;c.status="ok";c.note="rpm database";for(const auto&l:split(output,'\n')){auto flds=split(l,'\t');if(flds.size()==3&&!flds[0].empty())c.entries.emplace(flds[0],Json::Object{{"architecture",flds[2]},{"manager","rpm"},{"version",flds[1]}});}return c;}
namespace {
std::filesystem::path under(const std::filesystem::path&root,const std::filesystem::path&p){if(p.is_absolute())return root/p.relative_path();return root/p;}
bool wanted(const CaptureOptions&o,const std::string&c){return(o.include.empty()||o.include.count(c))&&!o.exclude.count(c);}
std::map<std::string,std::string> kv_file(const std::filesystem::path&p){std::map<std::string,std::string>m;std::ifstream f(p);std::string l;while(std::getline(f,l)){auto n=l.find('=');if(n==std::string::npos)continue;auto v=trim(l.substr(n+1));if(v.size()>=2&&v.front()=='"'&&v.back()=='"')v=v.substr(1,v.size()-2);m[l.substr(0,n)]=v;}return m;}
Category os(const CaptureOptions&o){Category c;auto p=under(o.root,"/etc/os-release");auto m=kv_file(p);if(m.empty()){c.note="/etc/os-release unavailable";return c;}c.status="ok";Json::Object v;for(const char*k:{"ID","VERSION_ID","VERSION_CODENAME","PRETTY_NAME"})if(m.count(k))v.emplace(k,m[k]);c.entries.emplace("distribution",Json(std::move(v)));struct utsname u{};if(uname(&u)==0)c.entries.emplace("runtime",Json::Object{{"architecture",u.machine},{"kernel_release",u.release}});return c;}
Category boot(const CaptureOptions&o){Category c;struct utsname u{};if(uname(&u)!=0){c.note="uname failed";return c;}c.status="ok";c.entries.emplace("kernel",Json::Object{{"release",u.release},{"architecture",u.machine}});auto lockdown=under(o.root,"/sys/kernel/security/lockdown");try{auto s=trim(read_file_bounded(lockdown,4096));c.entries.emplace("lockdown",Json::Object{{"state",s}});}catch(...){ }auto efi=under(o.root,"/sys/firmware/efi");std::error_code ec;c.entries.emplace("firmware",Json::Object{{"efi",std::filesystem::exists(efi,ec)}});return c;}
Category packages(const CaptureOptions&o){Category c;auto status=under(o.root,"/var/lib/dpkg/status");std::ifstream f(status);if(f){c.status="ok";c.note="dpkg database";std::map<std::string,std::string>b;std::string l;auto flush=[&](){if(b["Status"]=="install ok installed"&&!b["Package"].empty()){std::string arch=b["Architecture"];c.entries.emplace(b["Package"],Json::Object{{"architecture",arch},{"manager","dpkg"},{"version",b["Version"]}});}b.clear();};while(std::getline(f,l)){if(l.empty()){flush();continue;}if(l[0]==' '||l[0]=='\t')continue;auto n=l.find(':');if(n!=std::string::npos)b[l.substr(0,n)]=trim(l.substr(n+1));}flush();return c;}if(o.root=="/"){auto rpm=executable_path({"/usr/bin/rpm","/bin/rpm"});if(rpm){auto r=run_command(*rpm,{"-qa","--qf","%{NAME}\\t%{EPOCHNUM}:%{VERSION}-%{RELEASE}\\t%{ARCH}\\n"},5000);if(r.exit_code==0)return parse_rpm_query_output(r.out);c.note=r.timed_out?"rpm query timed out":"rpm query failed";return c;}}c.note="no supported package database found";return c;}
Category services(const CaptureOptions&o){
  Category c; const std::vector<std::string>dirs={"/usr/lib/systemd/system","/lib/systemd/system","/etc/systemd/system"};
  std::map<std::string,std::string>origin; std::error_code ec;
  for(const auto&d:dirs){auto path=under(o.root,d);if(!std::filesystem::is_directory(path,ec))continue;for(std::filesystem::directory_iterator it(path,std::filesystem::directory_options::skip_permission_denied,ec),end;it!=end;it.increment(ec)){auto n=it->path().filename().string();if(n.size()>8&&n.substr(n.size()-8)==".service")origin[n]=d;}}
  if(origin.empty()){c.note="systemd service unit directories unavailable or empty";return c;}
  c.status="ok"; auto wants=under(o.root,"/etc/systemd/system"); std::set<std::string>enabled;
  if(std::filesystem::is_directory(wants,ec))for(std::filesystem::recursive_directory_iterator it(wants,std::filesystem::directory_options::skip_permission_denied,ec),end;it!=end;it.increment(ec)){if(it.depth()>4){it.disable_recursion_pending();continue;}if(it->is_symlink(ec)){auto n=it->path().filename().string();if(n.size()>8&&n.substr(n.size()-8)==".service")enabled.insert(n);}}
  for(const auto&u:origin)c.entries.emplace(u.first,Json::Object{{"enabled",enabled.count(u.first)?"enabled":"disabled"},{"state_kind","persistent"},{"unit_origin",u.second}});
  if(o.include_transient&&o.root=="/"){
    auto ctl=executable_path({"/usr/bin/systemctl","/bin/systemctl"});
    if(ctl){auto r=run_command(*ctl,{"list-units","--type=service","--all","--no-legend","--plain"},3000);if(r.exit_code==0){for(auto&l:split(r.out,'\n')){std::istringstream is(l);std::string unit,load,active,sub;if(is>>unit>>load>>active>>sub){auto it=c.entries.find(unit);if(it!=c.entries.end()){auto obj=it->second.as_object();obj["active"]=Json(active);obj["sub"]=Json(sub);obj["state_kind"]=Json("mixed");it->second=Json(std::move(obj));}}}}else c.note="systemd units collected; transient query unavailable";}
    else c.note="systemd units collected; systemctl unavailable";
  }
  return c;
}
Json config_one(const std::filesystem::path&actual){struct stat st{};if(lstat(actual.c_str(),&st)!=0)return Json::Object{{"state",errno==EACCES?"unreadable":"absent"}};Json::Object j{{"gid",static_cast<std::int64_t>(st.st_gid)},{"mode",static_cast<std::int64_t>(st.st_mode&07777)},{"uid",static_cast<std::int64_t>(st.st_uid)}};if(S_ISLNK(st.st_mode)){j["state"]="symlink-not-followed";j["type"]="symlink";return Json(std::move(j));}if(!S_ISREG(st.st_mode)){j["state"]="present";j["type"]=S_ISDIR(st.st_mode)?"directory":"other";return Json(std::move(j));}j["type"]="regular";std::uint64_t size=0;try{j["sha256"]=sha256_file_nofollow(actual,64U*1024U*1024U,size);j["size"]=static_cast<std::int64_t>(size);j["state"]="hashed";}catch(const std::exception&e){j["state"]=std::string(e.what());j["size"]=static_cast<std::int64_t>(st.st_size);}return Json(std::move(j));}
Category configuration(const CaptureOptions&o){Category c;c.status="ok";std::vector<std::filesystem::path>paths={"/etc/fstab","/etc/ssh/sshd_config","/etc/sysctl.conf","/etc/default/grub","/etc/security/limits.conf"};paths.insert(paths.end(),o.config_paths.begin(),o.config_paths.end());std::set<std::string>seen;for(const auto&p:paths){if(!p.is_absolute()||p.string().size()>4096){c.status="partial";c.note="one or more non-absolute or oversized paths rejected";continue;}auto normalized=p.lexically_normal();if(normalized.string().find("..")!=std::string::npos){c.status="partial";c.note="unsafe path rejected";continue;}if(seen.insert(normalized.string()).second)c.entries.emplace(normalized.string(),config_one(under(o.root,normalized)));}return c;}
Category mounts(const CaptureOptions&o){Category c;auto p=under(o.root,"/proc/self/mountinfo");std::ifstream f(p);if(!f){c.note="mountinfo unavailable";return c;}c.status="ok";std::string l;while(std::getline(f,l)){auto sep=l.find(" - ");if(sep==std::string::npos)continue;auto left=split(l.substr(0,sep),' '),right=split(l.substr(sep+3),' ');if(left.size()<6||right.size()<2)continue;std::string mp=left[4];if(mp.rfind("/proc/",0)==0||mp.rfind("/sys/",0)==0||mp.rfind("/run/",0)==0)continue;std::set<std::string>keep;for(auto&x:split(left[5],','))if(x=="ro"||x=="rw"||x=="nosuid"||x=="nodev"||x=="noexec"||x=="relatime")keep.insert(x);std::string opts;for(const auto&x:keep){if(!opts.empty())opts+=',';opts+=x;}c.entries[mp]=Json::Object{{"filesystem",right[0]},{"options",opts}};}return c;}
Category hardware(const CaptureOptions&o){Category c;c.status="ok";std::error_code ec;auto blocks=under(o.root,"/sys/class/block");if(std::filesystem::is_directory(blocks,ec))for(std::filesystem::directory_iterator it(blocks,std::filesystem::directory_options::skip_permission_denied,ec),end;it!=end;it.increment(ec)){auto name=it->path().filename().string();if(name.rfind("loop",0)==0||name.rfind("ram",0)==0)continue;std::string removable="unknown";try{removable=trim(read_file_bounded(it->path()/"removable",16));}catch(...){ }c.entries.emplace("block:"+name,Json::Object{{"class","block"},{"removable",removable}});}auto net=under(o.root,"/sys/class/net");std::int64_t count=0;if(std::filesystem::is_directory(net,ec))for(std::filesystem::directory_iterator it(net,std::filesystem::directory_options::skip_permission_denied,ec),end;it!=end;it.increment(ec))if(it->path().filename()!="lo")++count;c.entries.emplace("network-interface-summary",Json::Object{{"count",count}});return c;}
Category repos(const CaptureOptions&o){Category c;c.status="ok";std::vector<std::filesystem::path>files;std::error_code ec;auto main=under(o.root,"/etc/apt/sources.list");if(std::filesystem::is_regular_file(main,ec))files.push_back(main);auto dir=under(o.root,"/etc/apt/sources.list.d");if(std::filesystem::is_directory(dir,ec))for(std::filesystem::directory_iterator it(dir,std::filesystem::directory_options::skip_permission_denied,ec),end;it!=end;it.increment(ec))if(it->is_regular_file(ec))files.push_back(it->path());auto ydir=under(o.root,"/etc/yum.repos.d");if(std::filesystem::is_directory(ydir,ec))for(std::filesystem::directory_iterator it(ydir,std::filesystem::directory_options::skip_permission_denied,ec),end;it!=end;it.increment(ec))if(it->is_regular_file(ec))files.push_back(it->path());std::sort(files.begin(),files.end());for(const auto&p:files){std::string rel="/"+std::filesystem::relative(p,o.root,ec).string();try{auto raw=read_file_bounded(p,1024U*1024U);auto lines=split(raw,'\n');Json::Array values;for(auto l:lines){l=trim(l);if(l.empty()||l[0]=='#')continue;auto pos=l.find("http");if(pos!=std::string::npos){auto end=l.find_first_of(" \t",pos);auto url=l.substr(pos,end==std::string::npos?std::string::npos:end-pos);l.replace(pos,url.size(),sanitize_repo_url(url));}auto lower=l;std::transform(lower.begin(),lower.end(),lower.begin(),[](unsigned char ch){return static_cast<char>(std::tolower(ch));});if(lower.find("password=")!=std::string::npos||lower.find("token=")!=std::string::npos||lower.find("secret=")!=std::string::npos||lower.find("private_key=")!=std::string::npos)l="[credential-bearing line omitted]";values.emplace_back(l);}c.entries.emplace(rel,Json::Object{{"normalized_lines",Json(std::move(values))}});}catch(...){c.status="partial";c.entries.emplace(rel,Json::Object{{"state","unreadable"}});}}if(files.empty()){c.status="unavailable";c.note="no supported repository configuration found";}return c;}
}
Snapshot capture(const CaptureOptions&o){Snapshot s;s.captured_at=utc_now();for(const auto&c:supported_categories())if(wanted(o,c)){if(c=="operating-system")s.categories[c]=os(o);else if(c=="boot-kernel")s.categories[c]=boot(o);else if(c=="packages")s.categories[c]=packages(o);else if(c=="services")s.categories[c]=services(o);else if(c=="configuration")s.categories[c]=configuration(o);else if(c=="mounts")s.categories[c]=mounts(o);else if(c=="hardware")s.categories[c]=hardware(o);else if(c=="repositories")s.categories[c]=repos(o);}return s;}
}
